var metric = 'metric' === ( v.units || 'metric' );
var kg = toKg( v, metric );
var cm = toCm( v, metric );
var age = num( v.age );

/* Mifflin-St Jeor, which predicts resting energy more accurately than
   Harris-Benedict for most modern populations. */
var bmr = ( 10 * kg ) + ( 6.25 * cm ) - ( 5 * age ) + ( 'female' === v.sex ? -161 : 5 );

if ( kg <= 0 || cm <= 0 ) {
	return { label: 'Basal metabolic rate', value: '\u2014', rows: [], note: 'Enter a height and a weight.' };
}

bmr = Math.max( bmr, 0 );

/* The four activity multipliers people actually meet, shown as rows rather
   than as a second field, because the question underneath a BMR search is
   almost always what it means for eating. */
var sedentary = bmr * 1.2;
var light = bmr * 1.375;
var moderate = bmr * 1.55;
var hard = bmr * 1.725;

return {
	label: 'Basal metabolic rate',
	value: decimals( bmr, 0 ) + ' kcal/day',
	sub: 'at rest, before any movement at all',
	bar: [
		{ pct: share( bmr, moderate ), color: ACCENT },
		{ pct: share( moderate - bmr, moderate ), color: NEUTRAL }
	],
	rows: [
		{ label: 'Desk job, little exercise', value: decimals( sedentary, 0 ) + ' kcal', color: ACCENT },
		{ label: 'Light exercise, 1 to 3 days', value: decimals( light, 0 ) + ' kcal' },
		{ label: 'Moderate exercise, 3 to 5 days', value: decimals( moderate, 0 ) + ' kcal' },
		{ label: 'Hard exercise, 6 to 7 days', value: decimals( hard, 0 ) + ' kcal', divide: true }
	],
	note: 'BMR is the floor, not a target. The rows below it add movement back in, and even the lowest of them assumes you get out of bed.'
}
